+	pc := newPCCounter("host-a")
+	stale := forget(t, x, pc, "goal-1", t0)
+	p, err := BeginRotate(x.b, AllParts, Auth{Recovery: x.rk}, Proof{}, testGen, nil, t0)
+	must(t, err)
+	nc, err := p.Commit(x.b, p.answer, t0.Add(time.Minute))
